import React, { useState } from 'react';
import '../styles/theme.css';

export default function Login({ onLoginSuccess }) {
  const [authMode, setAuthMode] = useState('login'); // 'login', 'signup', 'forgot', 'otp'
  const [formData, setFormData] = useState({
    mobile: '',
    password: '',
    name: '',
    confirmPassword: '',
    otp: ''
  });
  const [message, setMessage] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    if (!formData.mobile || !formData.password) {
      setMessage('Please enter mobile number and password.');
      return;
    }
    // Simulate successful login
    onLoginSuccess();
  };

  const handleSignupSubmit = (e) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      setMessage('Passwords do not match!');
      return;
    }
    alert('Account created successfully! Please login.');
    setAuthMode('login');
    setMessage('');
  };

  const handleSendOtp = (e) => {
    e.preventDefault();
    if (!formData.mobile) {
      setMessage('Please enter your registered mobile number.');
      return;
    }
    alert('OTP sent successfully to ' + formData.mobile + ' (Use 1234)');
    setAuthMode('otp');
    setMessage('');
  };

  const handleVerifyOtp = (e) => {
    e.preventDefault();
    if (formData.otp === '1234') {
      alert('OTP verified! You can now login or reset password.');
      setAuthMode('login');
      setMessage('');
    } else {
      setMessage('Invalid OTP. Use 1234');
    }
  };

  return (
    <div style={containerStyle}>
      <div style={cardStyle}>
        
        {/* Logo & Title */}
        <div style={{ textAlign: 'center', marginBottom: '20px' }}>
          <span style={{ fontSize: '32px' }}>🌾</span>
          <h2 style={{ color: '#1B4D3E', margin: '5px 0 0 0', fontSize: '22px' }}>RK SONS</h2>
          <p style={{ color: '#718096', fontSize: '12px', margin: '4px 0 0 0' }}>Grain Enterprise Management OS</p>
        </div>

        {message && <div style={errorStyle}>{message}</div>}

        {/* 1. LOGIN FORM */}
        {authMode === 'login' && (
          <form onSubmit={handleLoginSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            <div>
              <label style={labelStyle}>Mobile Number</label>
              <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter mobile number" style={inputStyle} required />
            </div>
            <div>
              <label style={labelStyle}>Password</label>
              <input type="password" name="password" value={formData.password} onChange={handleChange} placeholder="••••••••" style={inputStyle} required />
            </div>
            
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}>
              <span style={{ color: '#3182CE', cursor: 'pointer' }} onClick={() => { setAuthMode('signup'); setMessage(''); }}>Create Account</span>
              <span style={{ color: '#E53E3E', cursor: 'pointer' }} onClick={() => { setAuthMode('forgot'); setMessage(''); }}>Forgot Password?</span>
            </div>

            <button type="submit" style={primaryBtn}>LOGIN</button>
          </form>
        )}

        {/* 2. SIGN UP FORM */}
        {authMode === 'signup' && (
          <form onSubmit={handleSignupSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div>
              <label style={labelStyle}>Full Name</label>
              <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Enter your name" style={inputStyle} required />
            </div>
            <div>
              <label style={labelStyle}>Mobile Number</label>
              <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter mobile number" style={inputStyle} required />
            </div>
            <div>
              <label style={labelStyle}>Password</label>
              <input type="password" name="password" value={formData.password} onChange={handleChange} placeholder="Create password" style={inputStyle} required />
            </div>
            <div>
              <label style={labelStyle}>Confirm Password</label>
              <input type="password" name="confirmPassword" value={formData.confirmPassword} onChange={handleChange} placeholder="Confirm password" style={inputStyle} required />
            </div>

            <div style={{ textAlign: 'right', fontSize: '12px' }}>
              <span style={{ color: '#3182CE', cursor: 'pointer' }} onClick={() => { setAuthMode('login'); setMessage(''); }}>Already have an account? Login</span>
            </div>

            <button type="submit" style={primaryBtn}>REGISTER</button>
          </form>
        )}

        {/* 3. FORGOT PASSWORD (SEND OTP) */}
        {authMode === 'forgot' && (
          <form onSubmit={handleSendOtp} style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            <p style={{ fontSize: '13px', color: '#4A5568', textAlign: 'center', margin: 0 }}>Enter your registered mobile number to receive an OTP verification code.</p>
            <div>
              <label style={labelStyle}>Mobile Number</label>
              <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter mobile number" style={inputStyle} required />
            </div>

            <div style={{ textAlign: 'right', fontSize: '12px' }}>
              <span style={{ color: '#3182CE', cursor: 'pointer' }} onClick={() => { setAuthMode('login'); setMessage(''); }}>Back to Login</span>
            </div>

            <button type="submit" style={primaryBtn}>SEND OTP</button>
          </form>
        )}

        {/* 4. OTP VERIFICATION */}
        {authMode === 'otp' && (
          <form onSubmit={handleVerifyOtp} style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            <p style={{ fontSize: '13px', color: '#4A5568', textAlign: 'center', margin: 0 }}>Enter the 4-digit OTP sent to your phone (Demo OTP: 1234).</p>
            <div>
              <label style={labelStyle}>Enter OTP</label>
              <input type="text" name="otp" value={formData.otp} onChange={handleChange} placeholder="1234" maxLength="4" style={{ ...inputStyle, textAlign: 'center', letterSpacing: '8px', fontSize: '18px', fontWeight: 'bold' }} required />
            </div>

            <div style={{ textAlign: 'right', fontSize: '12px' }}>
              <span style={{ color: '#3182CE', cursor: 'pointer' }} onClick={() => { setAuthMode('login'); setMessage(''); }}>Back to Login</span>
            </div>

            <button type="submit" style={primaryBtn}>VERIFY OTP</button>
          </form>
        )}

